// ─── File: OwnershipDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.time.Duration;
import java.time.LocalDateTime;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class OwnershipDemo {

    private static final Logger log = Logger.getLogger(OwnershipDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Reconciliation freshness monitor at " + BANK_NAME);

        LocalDateTime now = LocalDateTime.of(2026, 10, 30, 6, 0);
        ReconciliationMonitor monitor = new ReconciliationMonitor(Duration.ofHours(24));

        // Healthy case: last success was 3 hours ago.
        JobStatus healthy = new JobStatus("ledger-recon", now.minusHours(3));
        monitor.check(healthy, now);

        // Overdue case: last success was 3 days ago — silent failure.
        JobStatus stale = new JobStatus("ledger-recon", now.minusDays(3));
        monitor.check(stale, now);
    }
}

// ─── Would be in model/JobStatus.java in a real project ───
class JobStatus {
    private final String jobName;
    private final LocalDateTime lastSuccess;

    JobStatus(String jobName, LocalDateTime lastSuccess) {
        this.jobName = jobName;
        this.lastSuccess = lastSuccess;
    }

    String getJobName() { return jobName; }
    LocalDateTime getLastSuccess() { return lastSuccess; }
}

// ─── Would be in monitor/ReconciliationMonitor.java in a real project ───
// Turns a silent failure into a loud alert — the durable form of ownership.
class ReconciliationMonitor {
    private static final Logger log = Logger.getLogger(ReconciliationMonitor.class.getName());
    private final Duration expectedInterval;

    ReconciliationMonitor(Duration expectedInterval) {
        this.expectedInterval = expectedInterval;
    }

    boolean check(JobStatus status, LocalDateTime now) {
        Duration sinceSuccess = Duration.between(status.getLastSuccess(), now);
        if (sinceSuccess.compareTo(expectedInterval) > 0) {
            log.severe(() -> "ALERT: " + status.getJobName() + " overdue. Last success "
                    + sinceSuccess.toHours() + "h ago (expected within "
                    + expectedInterval.toHours() + "h). Paging on-call.");
            return false;
        }
        log.info(() -> status.getJobName() + " healthy. Last success "
                + sinceSuccess.toHours() + "h ago.");
        return true;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
